import { test, expect } from '@playwright/test';

test.describe('Rate-Limit Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should display rate-limit error when submitting form too many times', async ({ page }) => {
    // Set up API interception for rate-limiting
    await page.route('**/api/submit-form', (route) => {
      route.abort('Rate limit exceeded');
    });

    // First successful submission
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();
    await page.waitForURL('**/api/submit-form');
    const successMessage = page.getByText(/success/i);
    await expect(successMessage).toBeVisible();

    // Second submission within rate limit window
    await submitButton.click();
    await page.waitForURL('**/api/submit-form');
    const errorMessage = page.getByText(/rate limit exceeded/i);
    await expect(errorMessage).toBeVisible();

    // Third submission should trigger error
    await submitButton.click();
    await page.waitForURL('**/api/submit-form');
    await expect(errorMessage).toBeVisible();

    // Verify error message is displayed
    await expect(errorMessage).toBeVisible();

    // Verify form is still visible
    const formContainer = page.getByRole('form');
    await expect(formContainer).toBeVisible();

    // Verify submit button is still enabled
    await expect(submitButton).toBeEnabled();
  });

  test('should clear rate-limit error after successful submission', async ({ page }) => {
    // Set up API interception for rate-limiting
    await page.route('**/api/submit-form', (route) => {
      route.abort('Rate limit exceeded');
    });

    // First submission
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();
    await page.waitForURL('**/api/submit-form');
    const successMessage = page.getByText(/success/i);
    await expect(successMessage).toBeVisible();

    // Second submission within rate limit window
    await submitButton.click();
    await page.waitForURL('**/api/submit-form');
    const errorMessage = page.getByText(/rate limit exceeded/i);
    await expect(errorMessage).toBeVisible();

    // Third submission should clear error
    await submitButton.click();
    await page.waitForURL('**/api/submit-form');
    await expect(errorMessage).not.toBeVisible();

    // Verify success message is still visible
    await expect(successMessage).toBeVisible();

    // Verify error message is gone
    await expect(errorMessage).not.toBeVisible();

    // Verify form is still visible
    const formContainer = page.getByRole('form');
    await expect(formContainer).toBeVisible();

    // Verify submit button is still enabled
    await expect(submitButton).toBeEnabled();
  });
});
